{
  "schema_version": 1,
  "case_id": "case-06-unsupported-snippet",
  "description": "A snippet that exists but does not support its claim.",
  "fixture_dir": "evals/fixtures/case-06-unsupported-snippet",
  "mockup": "index.html",
  "requirements_file": "evals/cases/case-06-unsupported-snippet/requirements.md",
  "checkpoints": {
    "1": {
      "answers": [
        {
          "match": {
            "keywords": [
              "manager"
            ]
          },
          "verbatim": "Managers approve claims from their own direct reports only.",
          "actions": [
            {
              "type": "approve_affected"
            },
            {
              "type": "clear_unknown_on_affected"
            }
          ]
        },
        {
          "match": {
            "keywords": [
              "reason"
            ]
          },
          "verbatim": "A reason is required when rejecting a claim.",
          "actions": [
            {
              "type": "approve_affected"
            },
            {
              "type": "clear_unknown_on_affected"
            }
          ]
        },
        {
          "match": {
            "keywords": [
              "export"
            ]
          },
          "verbatim": "The export is a CSV file of the audit log entries.",
          "actions": [
            {
              "type": "approve_affected"
            },
            {
              "type": "clear_unknown_on_affected"
            }
          ]
        }
      ],
      "remaining_requirements": {
        "decision": "approve",
        "verbatim": "Approve the remaining requirements as written."
      }
    },
    "2": {
      "gap_rules": [
        {
          "match": {
            "keywords": [
              "audit"
            ]
          },
          "decision": "approve",
          "verbatim": "Research the audit log gap.",
          "resolution_path": "research"
        }
      ],
      "max_research_gaps": 2,
      "unmatched_gaps": {
        "decision": "approve",
        "verbatim": "Approve this gap; research is limited to the first two research gaps."
      }
    },
    "3": {
      "answers": []
    }
  }
}

